use crate::aap::caps::state_rw;

struct Node;

impl Guest for Node {
    fn run(published: PublishedDigest) -> RunReport {
        let PublishedDigest {
            date,
            considered,
            published: was_published,
        } = published;

        let mut recorded: u32 = 0;

        // Only mark items as seen when the digest actually went out; otherwise
        // the next run should be free to consider them again.
        if was_published {
            for id in considered.iter() {
                if id.is_empty() {
                    continue;
                }
                state_rw::put(id, &date);
                recorded = recorded.saturating_add(1);
            }
        }

        RunReport { date, recorded }
    }
}

